local ScreenGui=Instance.new("ScreenGui")ScreenGui.Name="ASLauncherUI"ScreenGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling ScreenGui.ResetOnSpawn=false ScreenGui.Parent=game.Players.LocalPlayer:WaitForChild("PlayerGui")local LetterA=Instance.new("TextLabel")LetterA.Name="LetterA"LetterA.Size=UDim2.new(0,0,0,150)LetterA.Position=UDim2.new(-0.2,0,0.5,-75)LetterA.AnchorPoint=Vector2.new(0.5,0.5)LetterA.BackgroundTransparency=1 LetterA.Text="A"LetterA.TextColor3=Color3.fromRGB(0,255,255)LetterA.TextScaled=true LetterA.Font=Enum.Font.GothamBlack LetterA.TextStrokeTransparency=0 LetterA.TextStrokeColor3=Color3.new(0,0,0)LetterA.Parent=ScreenGui local LetterS=Instance.new("TextLabel")LetterS.Name="LetterS"LetterS.Size=UDim2.new(0,0,0,150)LetterS.Position=UDim2.new(1.2,0,0.5,-75)LetterS.AnchorPoint=Vector2.new(0.5,0.5)LetterS.BackgroundTransparency=1 LetterS.Text="S"LetterS.TextColor3=Color3.fromRGB(255,50,255)LetterS.TextScaled=true LetterS.Font=Enum.Font.GothamBlack LetterS.TextStrokeTransparency=0 LetterS.TextStrokeColor3=Color3.new(0,0,0)LetterS.Parent=ScreenGui local function addGlowEffect(textLabel,color)local glow=Instance.new("UIStroke")glow.Color=color glow.Thickness=4 glow.Transparency=0.5 glow.Parent=textLabel local glow2=Instance.new("UIStroke")glow2.Color=Color3.new(1,1,1)glow2.Thickness=2 glow2.Transparency=0.6 glow2.Parent=textLabel return{glow,glow2}end local aGlow=addGlowEffect(LetterA,Color3.fromRGB(0,150,255))local sGlow=addGlowEffect(LetterS,Color3.fromRGB(255,0,200))local SubTitle=Instance.new("TextLabel")SubTitle.Name="SubTitle"SubTitle.Size=UDim2.new(0,0,0,60)SubTitle.Position=UDim2.new(0.5,0,0.6,-30)SubTitle.AnchorPoint=Vector2.new(0.5,0.5)SubTitle.BackgroundTransparency=1 SubTitle.Text="SCRIPT HUB"SubTitle.TextColor3=Color3.fromRGB(200,200,200)SubTitle.TextScaled=true SubTitle.Font=Enum.Font.GothamBlack SubTitle.TextStrokeTransparency=0.5 SubTitle.TextStrokeColor3=Color3.new(0,0,0)SubTitle.Visible=false SubTitle.Parent=ScreenGui game:GetService("TweenService"):Create(LetterA,TweenInfo.new(2,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Size=UDim2.new(0,90,0,150),Position=UDim2.new(0.5,-45,0.5,-75)}):Play()wait(0.5)game:GetService("TweenService"):Create(LetterS,TweenInfo.new(2,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Size=UDim2.new(0,90,0,150),Position=UDim2.new(0.5,45,0.5,-75)}):Play()wait(2.5)game:GetService("TweenService"):Create(LetterA,TweenInfo.new(1,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Position=UDim2.new(0.5,-30,0.3,-50),Size=UDim2.new(0,60,0,100),TextColor3=Color3.fromRGB(255,255,255)}):Play()game:GetService("TweenService"):Create(LetterS,TweenInfo.new(1,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Position=UDim2.new(0.5,40,0.3,-50),Size=UDim2.new(0,60,0,100),TextColor3=Color3.fromRGB(255,255,255)}):Play()wait(1)SubTitle.Visible=true game:GetService("TweenService"):Create(SubTitle,TweenInfo.new(0.5,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{Size=UDim2.new(0,300,0,60)}):Play()wait(0.5)local success,err=pcall(function()Script Hub = "AS Script Hub"loadstring(game:HttpGet("https://raw.githubusercontent.com/maninffg/---/refs/heads/main/Script Hub.lua"))()end)if not success then SubTitle.Text="加载失败"SubTitle.TextColor3=Color3.fromRGB(255,50,50)wait(1.5)end for i=0,10 do LetterA.TextTransparency=i/10 LetterA.TextStrokeTransparency=i/10 LetterS.TextTransparency=i/10 LetterS.TextStrokeTransparency=i/10 SubTitle.TextTransparency=i/10 SubTitle.TextStrokeTransparency=i/10 wait(0.05)end ScreenGui:Destroy()
